const ROOT = process.cwd();
const DRY = process.argv.includes("--dry-run");
const UNDO = process.argv.includes("--undo");
const BAK = ".before-camera.bak";
const MARK = "Added by aura-camera-setup.cjs";
const SKIP_DIRS = new Set(["node_modules", "dist", "build", "out", "release", ".git", ".vite", "coverage", "tests", "supabase"]);

const rel = (p) => path.relative(ROOT, p) || p;
const say = (line = "") => console.log(line);
function stop(lines) {
  say();
  say("Nothing was changed.");
  (Array.isArray(lines) ? lines : [lines]).forEach((l) => say("  " + l));
  say();
  process.exit(1);
}
function readText(file) {
  const raw = fs.readFileSync(file, "utf8");
  const eol = raw.includes("\r\n") ? "\r\n" : "\n"; // keep Windows line endings as they are
  return { text: raw.replace(/\r\n/g, "\n"), eol };
}
const withEol = (text, eol) => (eol === "\n" ? text : text.replace(/\n/g, eol));
function* walk(dir, depth = 0) {
  if (depth > 7) return;
  let entries = [];
  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name) && !entry.name.startsWith(".")) yield* walk(full, depth + 1);
    } else if (/\.(jsx?|tsx?|cjs|mjs)$/.test(entry.name) && !/^aura-[\w-]+\.cjs$/.test(entry.name)) {
      try { if (fs.statSync(full).size < 3 * 1024 * 1024) yield full; } catch {}
    }
  }
}
// Finds one file. A project can have several that look alike, so `prefer` is a list of tie-breakers.
function findOne(label, test, hint, prefer = []) {
  let hits = [];
  for (const file of walk(ROOT)) {
    let text = "";
    try { text = fs.readFileSync(file, "utf8"); } catch { continue; }
    if (test(text)) hits.push({ file, text });
  }
  if (!hits.length) stop(["I couldn't find " + label + ".", hint, "Copy this message to Claude."]);
  for (const rule of prefer) {
    if (hits.length === 1) break;
    const kept = hits.filter((h) => rule(h));
    if (kept.length) hits = kept;
  }
  if (hits.length === 1) return hits[0].file;
  stop(["I found more than one file that looks like " + label + ":", ...hits.map((h) => "  " + rel(h.file)), "Copy this message to Claude."]);
}
const sameFile = (a, b) => path.resolve(a).toLowerCase() === path.resolve(b).toLowerCase();
const indentOf = (line) => line.match(/^\s*/)[0];
const findLine = (lines, re, from = 0, to = lines.length) => { for (let i = from; i < to; i++) if (re.test(lines[i])) return i; return -1; };

function swapOnce(text, find, replace, what) {
  const i = text.indexOf(find);
  if (i < 0 || text.indexOf(find, i + 1) >= 0) throw new Error(what);
  return text.slice(0, i) + replace + text.slice(i + find.length);
}

function swapAll(text, find, replace, count, what) {
  const n = text.split(find).length - 1;
  if (n !== count) throw new Error(what);
  return text.split(find).join(replace);
}
function editApp(text) {
  if (text.includes("./components/camera")) return { text, notes: [] };
  let t = text;
  const imp = /^import \{ useCloudGames, useCloudProfile \} from "\.\/cloudsync";\n/m;
  if (!imp.test(t)) throw new Error('the imports at the top ( import { useCloudGames, useCloudProfile } from "./cloudsync"; )');
  t = t.replace(imp, (m) => m + 'import { CameraButton, CameraPanel, CameraSettings, cameraOverlay } from "./components/camera"; // the camera (' + MARK + ")\n");
  // Settings: what the camera remembers (which one, mirror, size, where the preview is)
  t = swapOnce(t, '  recordSourceName: "",\n};\n',
    '  recordSourceName: "",\n' +
    "  // Camera (" + MARK + ")\n" +
    '  camDevice: "",         // the camera to use ("" = the one Windows picks)\n' +
    '  camDeviceName: "",\n' +
    "  camMirror: true,       // the preview shows you like a mirror (recordings never are)\n" +
    "  camWidth: 320,         // preview size\n" +
    "  camX: null, camY: null,// where the preview is (null: bottom right)\n" +
    "  camInRecordings: false,// put the camera in a corner of clips while it's on\n" +
    '  camCorner: "br",\n' +
    "};\n",
    "the settings list ( recordSourceName: \"\", }; )");
  // F9 / AURA Bar recordings
  t = swapOnce(t,
    "  quickRec.starting = true;\n  let screenStream = null;\n",
    "  quickRec.starting = true;\n  let screenStream = null;\n  let camShot = null; // the camera in a corner, when it's on and switched on in Settings (" + MARK + ")\n",
    "the F9 recording ( quickRec.starting = true; let screenStream = null; )");
  t = swapOnce(t,
    "    const combined = new MediaStream([...screenStream.getVideoTracks(), ...dest.stream.getAudioTracks()]);\n",
    "    if (SETTINGS.camInRecordings) camShot = cameraOverlay(screenStream.getVideoTracks()[0], { corner: SETTINGS.camCorner });\n" +
    "    const combined = new MediaStream([...(camShot ? [camShot.track] : screenStream.getVideoTracks()), ...dest.stream.getAudioTracks()]);\n",
    "the F9 recording's picture ( const combined = new MediaStream([...screenStream.getVideoTracks(), ... )");
  t = swapOnce(t,
    "    quickRec.cleanup = () => {\n      [screenStream, micStream, combined].forEach((st) => st?.getTracks().forEach((t) => t.stop()));\n",
    "    quickRec.cleanup = () => {\n      camShot?.stop();\n      [screenStream, micStream].forEach((st) => st?.getTracks().forEach((t) => t.stop()));\n      if (!camShot) combined.getTracks().forEach((t) => t.stop()); // (with the camera, its own track stays on)\n" +
    "      dest.stream.getTracks().forEach((t) => t.stop());\n",
    "the end of an F9 recording ( quickRec.cleanup = () => { ... )");
  t = swapOnce(t,
    "    if (quickRec.cleanup) quickRec.cleanup();\n    else screenStream?.getTracks().forEach((t) => t.stop());\n",
    "    if (quickRec.cleanup) quickRec.cleanup();\n    else { camShot?.stop(); screenStream?.getTracks().forEach((t) => t.stop()); }\n",
    "when an F9 recording can't start ( if (quickRec.cleanup) quickRec.cleanup(); ... )");
  // Clips page recordings
  t = swapOnce(t,
    "      const combined = new MediaStream([\n        ...stream.getVideoTracks(),\n        ...destination.stream.getAudioTracks(),\n      ]);\n",
    "      // The camera in a corner, when it's on and switched on in Settings (" + MARK + ")\n" +
    "      const camShot = SETTINGS.camInRecordings ? cameraOverlay(stream.getVideoTracks()[0], { corner: SETTINGS.camCorner }) : null;\n" +
    "      const combined = new MediaStream([\n        ...(camShot ? [camShot.track] : stream.getVideoTracks()),\n        ...destination.stream.getAudioTracks(),\n      ]);\n",
    "the Clips page recording's picture ( const combined = new MediaStream([ ...stream.getVideoTracks(), ... )");
  t = swapOnce(t,
    "        await window.electronAPI.stopFfmpegPipe();\n        combined.getTracks().forEach(t => t.stop());\n",
    "        await window.electronAPI.stopFfmpegPipe();\n        camShot?.stop();\n        [...stream.getTracks(), ...destination.stream.getTracks()].forEach(t => t.stop());\n        if (!camShot) combined.getTracks().forEach(t => t.stop());\n",
    "the end of a Clips page recording ( combined.getTracks().forEach(t => t.stop()); )");
  // Settings > Camera, after Recording
  t = swapOnce(t,
    '      <div className="ss">\n        <div className="ss-t">LIBRARY</div>\n',
    "      {/* The camera (" + MARK + ") */}\n      <CameraSettings settings={s} onChange={set} Seg={Seg}/>\n" +
    '      <div className="ss">\n        <div className="ss-t">LIBRARY</div>\n',
    "the Settings page's Library section ( <div className=\"ss-t\">LIBRARY</div> )");
  // The Camera item above Log out, in both menu styles
  t = swapOnce(t, "              <LogoutButton rail open={sidebarOpen}/>\n",
    "              <CameraButton rail open={sidebarOpen} settings={settings}/>{/* (" + MARK + ") */}\n              <LogoutButton rail open={sidebarOpen}/>\n",
    "the Log out button in the slim menu ( <LogoutButton rail open={sidebarOpen}/> )");
  t = swapOnce(t, "          {/* Log out, at the bottom of the sidebar */}\n",
    "          <CameraButton open={sidebarOpen} settings={settings}/>{/* the camera (" + MARK + ") */}\n          {/* Log out, at the bottom of the sidebar */}\n",
    "the Log out button in the side menu ( {/* Log out, at the bottom of the sidebar */} )");
  // The floating preview, in both layouts
  t = swapAll(t, "<ControllerHUD/>\n", "<ControllerHUD/>\n<CameraPanel settings={settings} onSettings={updateSettings}/>\n", 2, "the two layouts ( <ControllerHUD/> twice )");
  // keep the indentation of each <ControllerHUD/> line
  t = t.replace(/^(\s*)<ControllerHUD\/>\n<CameraPanel /gm, "$1<ControllerHUD/>\n$1<CameraPanel ");
  return { text: t, notes: [
    "a Camera item above Log out opens a floating camera preview",
    "Settings > Camera: which camera, mirror, size, and the camera in recordings (off unless you switch it on)",
    "recordings with F9, the AURA Bar or the Clips page put the camera in a corner, only while it's on and that's switched on",
  ] };
}

// ── AURA's checks (only when they are installed) ─────────────────────────────
function editRunner(text) {
  if (/camera\.cjs/.test(text)) return { text, notes: [] };
  const lines = text.split("\n");
  let at = -1;
  for (let i = 0; i < lines.length; i++) if (/add\("window",/.test(lines[i])) at = i;
  if (at < 0) return { text, notes: ["(couldn't find where to add the check, so npm test doesn't include it)"] };
  lines.splice(at + 1, 0, 'if (fs.existsSync(path.join(__dirname, "camera.cjs"))) add("window", "The camera: preview, settings, recordings", "camera.cjs");');
  return { text: lines.join("\n"), notes: ["npm test now checks the camera too"] };
}

// Does `node` accept the file? Catches a bad edit before anything is written.
function syntaxProblem(text) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "aura-check-"));
  const file = path.join(dir, "check.cjs");
  try {
    fs.writeFileSync(file, text);
    const r = spawnSync(process.execPath, ["--check", file], { encoding: "utf8" });
    return r.status === 0 ? "" : String(r.stderr || "syntax error").split("\n").filter(Boolean).slice(0, 4).join(" | ");
  } catch { return ""; } finally { try { fs.rmSync(dir, { recursive: true, force: true }); } catch {} }
}

// ── Undo ──────────────────────────────────────────────────────────────────────
function undo() {
  let restored = 0;
  const visit = (dir, depth = 0) => {
    if (depth > 7) return;
    let entries = [];
    try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch { return; }
    for (const entry of entries) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if ((!SKIP_DIRS.has(entry.name) || entry.name === "tests") && !entry.name.startsWith(".")) visit(full, depth + 1);
      } else if (entry.name.endsWith(BAK)) {
        const target = full.slice(0, -BAK.length);
        fs.copyFileSync(full, target); fs.unlinkSync(full);
        say("  restored  " + rel(target)); restored++;
      } else if ((entry.name === "camera.cjs" || entry.name === "camera.jsx")) {
        try { if (fs.readFileSync(full, "utf8").includes(MARK)) { fs.unlinkSync(full); say("  removed   " + rel(full)); restored++; } } catch {}
      }
    }
  };
  say();
  visit(ROOT);
  say(restored ? "Undo finished. The camera is gone from AURA." : "Nothing to undo.");
  say();
}

// ── Run ───────────────────────────────────────────────────────────────────────
function run() {
  const pkgFile = path.join(ROOT, "package.json");
  if (!fs.existsSync(pkgFile)) stop(["This isn't your AURA project folder (no package.json here).", "Move this file next to package.json and run it from there."]);
  if (UNDO) return undo();

  const need = "Make sure this file is in your AURA project folder, next to package.json.";
  let pkgMain = "";
  try { pkgMain = String(JSON.parse(fs.readFileSync(pkgFile, "utf8")).main || ""); } catch {}
  const startFile = pkgMain ? path.resolve(ROOT, pkgMain) : "";
  const comp = (h) => /[\\/]components[\\/]/.test(h.file);
  const files = {
    app: findOne("your App file", (t) => /function AuraApp\s*\(/.test(t) && /<AuraApp\b/.test(t), need, [
      (h) => /^App\.[jt]sx?$/.test(path.basename(h.file)),
    ]),
  };

  const plan = [];
  const problems = [];
  const consider = (label, file, edit, checkSyntax) => {
    const { text, eol } = readText(file);
    try {
      const result = edit(text);
      if (checkSyntax && result.text !== text) { const bad = syntaxProblem(result.text); if (bad) throw new Error("a way to edit it safely (" + bad + ")"); }
      plan.push({ label, file, before: text, after: result.text, eol, notes: result.notes });
    } catch (e) { problems.push("In " + rel(file) + " I couldn't find " + e.message + "."); }
  };
  consider("App file", files.app, editApp, false);
  const runner = path.join(ROOT, "tests", "run.cjs");
  const hasChecks = fs.existsSync(runner);
  if (hasChecks) consider("checks", runner, editRunner, true);

  const created = [{ label: "camera", file: path.join(path.dirname(files.app), "components", "camera.jsx"), content: FILES.camera }];
  if (hasChecks) created.push({ label: "checks", file: path.join(ROOT, "tests", "camera.cjs"), content: FILES.test });
  for (const c of created) {
    c.note = "created";
    if (fs.existsSync(c.file)) {
      const existing = readText(c.file).text;
      if (!existing.includes(MARK)) problems.push(rel(c.file) + " already exists and wasn't made by this script, so I left it alone.");
      else c.note = existing === c.content ? "already done" : "updated";
    }
  }
  if (problems.length) stop([...problems, "Copy this message to Claude."]);

  say();
  say(DRY ? "Dry run. This is what would change:" : "AURA: the camera");
  say();
  for (const step of plan) {
    if (step.after !== step.before && !DRY) {
      const bak = step.file + BAK;
      if (!fs.existsSync(bak)) fs.copyFileSync(step.file, bak);
      fs.writeFileSync(step.file, withEol(step.after, step.eol));
    }
    say("  " + (step.label + ":").padEnd(13) + rel(step.file));
    (step.notes.length ? step.notes : ["already done"]).forEach((n) => say("               - " + n));
  }
  for (const c of created) {
    if (c.note !== "already done" && !DRY) { fs.mkdirSync(path.dirname(c.file), { recursive: true }); fs.writeFileSync(c.file, c.content); }
    say("  " + (c.label + ":").padEnd(13) + rel(c.file));
    say("               - " + c.note);
  }
  say();
  if (DRY) { say("Run it again without --dry-run to apply."); say(); return; }
  say("Done. Restart AURA (stop it in the terminal and start it again), then press Camera in the side menu (above Log out).");
  if (hasChecks) say("Run  npm test  before your next release.");
  say("To undo later:  node aura-camera-setup.cjs --undo");
  say();
}

try { run(); } catch (e) { stop(["Something unexpected went wrong: " + e.message, "Copy this message to Claude."]); }
